INSERT INTO services(slug,icon,title,short_text,description,features,sort_order) VALUES('structural-design','blueprint','Structural Design','Load-bearing systems engineered for seismic and wind resilience.','We model, analyze and certify structural frames for residential, commercial and industrial buildings — covering RCC, steel and composite systems, with full seismic-zone compliance for Nepal''s building code (NBC).','["Seismic & wind load analysis","RCC & structural steel detailing","Foundation & retaining design","Peer-review & code compliance"]',0);
INSERT INTO services(slug,icon,title,short_text,description,features,sort_order) VALUES('site-supervision','hardhat','Site Supervision','Daily on-ground quality control from foundation to finish.','Our resident engineers track every pour, weld and course of masonry against drawing tolerances, keeping contractors accountable and clients informed with weekly progress reporting.','["Daily site inspection logs","Material testing coordination","Contractor accountability audits","Weekly photo-based progress reports"]',1);
INSERT INTO services(slug,icon,title,short_text,description,features,sort_order) VALUES('geotechnical','strata','Geotechnical Investigation','Soil testing and bearing-capacity reports before you break ground.','Sub-surface investigation, bore-log analysis and bearing capacity reporting so foundation design starts from real ground data instead of assumptions.','["Bore hole & SPT testing","Bearing capacity reports","Slope stability assessment","Ground water analysis"]',2);
INSERT INTO services(slug,icon,title,short_text,description,features,sort_order) VALUES('road-infrastructure','road','Road & Infrastructure','Pavement design and drainage planning for public and private roads.','From rural access roads to municipal pavement rehabilitation, we handle alignment survey, pavement design and stormwater drainage planning.','["Alignment & topographic survey","Flexible & rigid pavement design","Stormwater drainage planning","Culvert & retaining structures"]',3);
INSERT INTO services(slug,icon,title,short_text,description,features,sort_order) VALUES('project-management','blueprint','Construction Project Management','One accountable team from permits to final handover.','We coordinate architects, contractors and vendors under a single schedule and budget, so you get one point of accountability from permitting through handover.','["Cost estimation & BOQ","Vendor & schedule coordination","Budget tracking","Final handover documentation"]',4);
INSERT INTO services(slug,icon,title,short_text,description,features,sort_order) VALUES('renovation-retrofit','hardhat','Renovation & Seismic Retrofit','Strengthening existing structures to meet current safety codes.','Structural assessment and retrofit design for older buildings — jacketing, bracing and foundation underpinning to bring them up to current seismic standards.','["Structural health assessment","Column & beam jacketing","Seismic bracing design","Underpinning & foundation repair"]',5);
INSERT INTO services(slug,icon,title,short_text,description,features,sort_order) VALUES('quality-testing','strata','Quality Testing & Inspection','Material verification and compliance testing for every pour and weld.','Concrete cube testing, rebar verification and weld inspection to ensure materials meet design specifications and code requirements.','["Concrete cube compression tests","Rebar & material verification","Weld inspection & certification","Compliance reporting"]',6);
INSERT INTO services(slug,icon,title,short_text,description,features,sort_order) VALUES('permitting','road','Permitting & Regulatory Compliance','Navigating municipal approvals and code compliance for your project.','We prepare and submit drawing packages to municipal authorities, track approvals, and handle any required revisions to ensure your project meets all regulatory requirements.','["Drawing package preparation","Municipal submission & tracking","Code compliance review","Revision handling"]',7);
INSERT INTO workflow_steps(step,title,description,sort_order) VALUES('01','Site Assessment','Ground survey, soil testing and existing-condition review to establish real constraints before any design starts.',0);
INSERT INTO workflow_steps(step,title,description,sort_order) VALUES('02','Design & Analysis','Structural modelling, load calculations and drawings, reviewed against NBC seismic code and client brief.',1);
INSERT INTO workflow_steps(step,title,description,sort_order) VALUES('03','Permitting','Drawing package prepared and submitted to the municipal authority; we track approval and handle revisions.',2);
INSERT INTO workflow_steps(step,title,description,sort_order) VALUES('04','Construction','Resident supervision through every pour and structural milestone, with weekly reporting back to you.',3);
INSERT INTO workflow_steps(step,title,description,sort_order) VALUES('05','Quality Testing','Concrete cube tests, rebar checks and material verification logged against design tolerances.',4);
INSERT INTO workflow_steps(step,title,description,sort_order) VALUES('06','Handover','Final walkthrough, as-built drawings and completion documentation delivered on close-out.',5);
INSERT INTO projects(id,category,year,title,location,summary,detail,scope,stats,image,sort_order) VALUES(1,'commercial',2024,'Baneshwor Commercial Tower','New Baneshwor, Kathmandu','A 9-storey mixed-use commercial tower with a base-isolated structural system.','Structural design and full-time site supervision for a 9-storey RCC commercial tower. The project required a base-isolation system to meet enhanced seismic performance targets requested by the client, along with a two-level basement parking structure below the water table.','["Structural Design","Geotechnical Investigation","Site Supervision"]','{"Floors":"9 + 2 basement","Area":"42,000 sq.ft","Duration":"22 months"}','project-1.jpg',0);
INSERT INTO projects(id,category,year,title,location,summary,detail,scope,stats,image,sort_order) VALUES(2,'residential',2023,'Budhanilkantha Residence Cluster','Budhanilkantha, Kathmandu','Eight private residences engineered on a shared sloped plot with retaining terraces.','Full structural design for eight independent residences on a steeply sloped 2-acre plot. Delivered a terraced retaining-wall system that let each home sit on a level pad while sharing a single stormwater drainage network.','["Structural Design","Site Supervision","Road & Infrastructure"]','{"Units":"8 residences","Area":"2 acres","Duration":"14 months"}','project-2.jpg',1);
INSERT INTO projects(id,category,year,title,location,summary,detail,scope,stats,image,sort_order) VALUES(3,'infrastructure',2022,'Sarlahi Rural Access Road','Sarlahi District','11 km of rural access road with culvert crossings and drainage rehabilitation.','Alignment survey and pavement design for an 11 km rural access road connecting four village clusters. Scope included six reinforced-concrete culvert crossings and a full stormwater drainage rehabilitation to prevent monsoon washout.','["Road & Infrastructure","Geotechnical Investigation","Construction Project Management"]','{"Length":"11 km","Culverts":"6 crossings","Duration":"9 months"}','project-3.jpg',2);
INSERT INTO projects(id,category,year,title,location,summary,detail,scope,stats,image,sort_order) VALUES(4,'retrofit',2023,'Patan Heritage School Retrofit','Patan, Lalitpur','Seismic retrofit of a 1960s masonry school building, in active use throughout.','Structural assessment and seismic retrofit of a 1960s unreinforced masonry school building. Work included column jacketing, steel bracing and a new reinforced roof diaphragm, phased across school holidays to avoid disrupting classes.','["Renovation & Seismic Retrofit","Structural Design","Site Supervision"]','{"Built":"1962","Floors":"3","Duration":"11 months"}','project-4.jpg',3);
INSERT INTO projects(id,category,year,title,location,summary,detail,scope,stats,image,sort_order) VALUES(5,'commercial',2021,'Pokhara Lakeside Hotel','Lakeside, Pokhara','A 40-room boutique hotel built on soft lakeside soil requiring piled foundations.','Geotechnical investigation revealed poor bearing capacity near the lakeshore, so we designed a piled raft foundation system and supervised construction of the 40-room boutique hotel above it.','["Geotechnical Investigation","Structural Design","Construction Project Management"]','{"Rooms":"40","Floors":"5","Duration":"18 months"}','project-5.jpg',4);
INSERT INTO projects(id,category,year,title,location,summary,detail,scope,stats,image,sort_order) VALUES(6,'residential',2020,'Dhulikhel Hillside Villa','Dhulikhel, Kavre','A single private villa cantilevered over a hillside slope.','Structural design for a private hillside villa, including a cantilevered living deck engineered to clear a 30-degree slope without additional ground support columns.','["Structural Design","Geotechnical Investigation"]','{"Area":"5,200 sq.ft","Slope":"30°","Duration":"10 months"}','project-6.jpg',5);
